136	// for the MOMENTUM pace chart. durationSeconds sizes the bucket array even past
137	// the last event (e.g. while the fight is still being reviewed).
138	export function derivePaceBuckets(
139	  events: Event[],
140	  fps: number,
141	  durationSeconds: number,
142	  bucketSeconds = 30,
143	): { red: number[]; blue: number[] } {
144	  const lastEventSeconds = events.reduce((max, e) => Math.max(max, e.frame / fps), 0);
145	  const totalSeconds = Math.max(durationSeconds, lastEventSeconds);
146	  const bucketCount = Math.max(2, Math.ceil(totalSeconds / bucketSeconds));
147	
148	  const red = new Array<number>(bucketCount).fill(0);
149	  const blue = new Array<number>(bucketCount).fill(0);
150	
151	  for (const e of events) {
152	    const m = e.description.match(STRIKE_RE);
153	    if (!m) continue;
154	
155	    const strikeType = m[2].toLowerCase();
156	    const outcome = m[3]?.toLowerCase() ?? null;
157	    const landed = outcome === 'landed' || strikeType.startsWith('clinch_') || strikeType.startsWith('ground_');
158	    if (!landed) continue;
159	
160	    const bucket = Math.min(bucketCount - 1, Math.floor(e.frame / fps / bucketSeconds));
161	    const arr = m[1].toLowerCase() === 'fighter_red' ? red : blue;
162	    arr[bucket] += 1;
163	  }
164	
165	  return { red, blue };
166	}
